export const code = async (inputs) => {
  const rows = inputs.sheets_rows;

  // Map each row to a structured JSON object
  const price_list_json = rows.map(row => ({
    package: row.values['Package Name'] || '',
    services: (row.values['Services Included'] || '').split('+').map(s => s.trim()),
    price: row.values['Suggested Pricing Tier'] || ''
  }));

  // Return as an output object that other nodes can use
  return {
    price_list_json
  };
};

export const code = async (inputs) => {
  // Parse inputs to numbers
  const gmtOffset = parseFloat(inputs.gmtOffset);
  const targetHour = 9;

  // Get current time
  const now = new Date();

  // Create target send time
  const sendTime = new Date();
  const targetUTCHour = targetHour - gmtOffset;
  sendTime.setUTCHours(targetUTCHour, 0, 0, 0);

  // If already passed, add one day
  if (sendTime.getTime() < now.getTime()) {
    sendTime.setDate(sendTime.getDate() + 1);
  }

  // Calculate delay
  const delayMs = sendTime.getTime() - now.getTime();
  const delayMinutes = Math.max(0, Math.floor(delayMs / 60000));

  return {
    delayMinutes: delayMinutes
  };
};

export const code = async (inputs) => {
  const headers = inputs.apiResponse.payload.headers;

  const messageIdHeader = headers.find(h => h.name === 'Message-Id');

  return {
    message_id: messageIdHeader ? messageIdHeader.value : null
  };
};

